\section{Introduction}

\subsection{The mechanism}
Autoregressive decoding is latency-bound by its sequentiality: token $n+1$ cannot be computed
before token $n$. Speculative decoding breaks the dependency by exploiting an asymmetry in
cost: scoring $d$ candidate continuations costs a large transformer roughly what generating
one token costs, because the $d$ positions are evaluated in parallel within one forward pass.
Thus: a small \emph{draft} model generates $d$ candidates; the large \emph{target} model
scores all $d$ positions in one batched pass; the longest agreeing prefix is committed, the
first disagreement is corrected by the target's own distribution, and the suffix is discarded.
The output distribution is exactly the target's, so the speedup costs nothing in quality. The
only tunable is the depth $d$.

\subsection{The tuning problem}
Depth trades two errors. Small $d$ underuses the verification pass. Large $d$ overspends
draft-model time on tokens discarded at the first disagreement, and the probability of
surviving to position $d$ decays. Current practice is to sweep, which is expensive (end-to-end
timing at every depth, on deployment hardware, per workload) and opaque (a number without a
mechanism). We ask whether the depth can be \emph{derived} from a measurement that never
touches the clock.

\subsection{Contributions}
We isolate the survival curve as the microscopic state variable, derive the cost law as its
macroscopic image, and give the full first- and second-order theory of that functional,
together with existence, comparative statics, closed forms for named families, an
impossibility theorem, a stability theorem, and a tight error-amplification law for the
estimator that in practice produces the survival curve. We then instantiate everything on
measured data and account for both what the measurement got right and what it got wrong.

\section{The Cost Law}

\begin{definition}[Survival curve]
A \emph{survival curve} is a sequence $s=(s_0,s_1,\dots)$ of reals. Semantically $s_i\in[0,1]$
is the probability that the accepted run of a speculative block survives past position $i$,
equivalently that drafted token number $i+1$ is accepted. The physically expected regime is
$s$ nonincreasing.
\end{definition}

We state the theory for arbitrary real sequences and introduce monotonicity and range
constraints only where needed: the measured curves of Section~\ref{sec:measured} violate both,
and it matters exactly which theorems still apply.

\begin{definition}[Cumulative acceptance]
$A(d)=\sum_{i<d}s_i$, so $A(0)=0$ and $A(d+1)=A(d)+s_d$.
\end{definition}

\begin{proposition}[Tail-sum bridge]\label{prop:abel}
For every survival curve and every $d$,
\[
A(d)\;=\;\sum_{i<d}(i+1)\bigl(s_i-s_{i+1}\bigr)\;+\;d\,s_d .
\]
\end{proposition}

\begin{proof}
Induction on $d$. Both sides vanish at $d=0$. For the step, the left side grows by $s_d$,
while the right grows by $(d+1)(s_d-s_{d+1})+(d+1)s_{d+1}-d\,s_d=s_d$.
\end{proof}

Reading $p_i=s_i-s_{i+1}$ as the probability that the run has length exactly $i+1$ and $s_d$
as the probability of saturating the block, Proposition~\ref{prop:abel} says
$A(d)=\mathbb{E}[\min(L,d)]$ for the run length $L$: cumulative acceptance is the expected
truncated run length. This is the formal bridge from micro-mechanism to macro-observable.

\begin{definition}[Overhead and cost law]
$c\ge0$ is the cost of drafting one token in units of one verification pass, so a depth-$d$
round costs $1+cd$. The \emph{gain} is
\[
G(d)=G_{c,s}(d)=\frac{A(d)}{1+cd},
\]
verified output tokens per unit verification-equivalent cost. The \emph{marginal} is
\[
M(d)=M_{c,s}(d)=s_d(1+cd)-c\,A(d).
\]
\end{definition}

\section{First-Order Theory}

\begin{theorem}[Marginal test]\label{thm:marginal}
For $c\ge0$ and any $s,d$:
$G(d)\le G(d+1)\iff M(d)\ge0$, and $G(d+1)<G(d)\iff M(d)<0$.
\end{theorem}

\begin{proof}
Both denominators are strictly positive, so $G(d)\le G(d+1)$ is equivalent to
$A(d)(1+c(d+1))\le (A(d)+s_d)(1+cd)$. Expanding and cancelling $A(d)(1+cd)$ leaves
$c\,A(d)\le s_d(1+cd)$, i.e.\ $M(d)\ge0$. The strict form is the contrapositive.
\end{proof}

\begin{theorem}[Equilibrium law]\label{thm:equilibrium}
For $c\ge0$, $\;M(d)<0\iff s_d<c\,G(d)$. Hence if $G(d+1)<G(d)$ then $s_d<c\,G(d)$, and if
$G(d)\le G(d+1)$ then $s_d\ge c\,G(d)$.
\end{theorem}

\begin{proof}
$c\,G(d)=c\,A(d)/(1+cd)$; multiplying $s_d<c\,A(d)/(1+cd)$ by $1+cd>0$ gives
$s_d(1+cd)<c\,A(d)$, i.e.\ $M(d)<0$.
\end{proof}

This is the central structural statement. The left-hand side $s_d$ is \emph{microscopic}: one
entry of the survival curve, obtainable from acceptance logs with no timing information. The
right-hand side $c\,G(d)$ is \emph{macroscopic}: the pipeline's throughput, scaled by the
overhead. The optimum is exactly the crossing. Economically, an extra draft costs $c$
verification-units, which deployed at the current rate would have produced $c\,G(d)$ output
tokens; the extra draft instead returns an expected $s_d$. Deepen while direct return exceeds
opportunity cost. Theorem~\ref{thm:equilibrium} says this intuition is not an approximation
but the exact criterion. The crossing is self-referential: the threshold rises as long as
deepening helps.

\section{Second-Order Theory: Concavity, Unimodality, Myopia}

\begin{theorem}[Marginal increment]\label{thm:increment}
$M(d+1)-M(d)=\bigl(1+c(d+1)\bigr)\bigl(s_{d+1}-s_d\bigr)$.
\end{theorem}

\begin{proof}
$M(d+1)-M(d)=s_{d+1}(1+c(d+1))-s_d(1+cd)-c\,s_d$, and the last two terms combine to
$-s_d(1+c(d+1))$.
\end{proof}

\begin{corollary}[Discrete concavity]\label{cor:concave}
If $c\ge0$ and $s$ is nonincreasing then $M$ is nonincreasing.
\end{corollary}

\begin{theorem}[No recovery]\label{thm:norecovery}
Let $c\ge0$, $s$ nonincreasing and $M(d)<0$. Then $G(e)\le G(d)$ for all $e\ge d$.
\end{theorem}

\begin{proof}
By Corollary~\ref{cor:concave}, $M(n)\le M(d)<0$ for $n\ge d$; Theorem~\ref{thm:marginal} then
gives $G(n+1)<G(n)$ at each step, and the inequalities chain.
\end{proof}

\begin{theorem}[Monotone ascent]\label{thm:ascent}
Let $c\ge0$ and $M(e)\ge0$ for all $e<d$. Then $G(e)\le G(d)$ for all $e\le d$. No
monotonicity of $s$ is required.
\end{theorem}

\begin{proof}
Induction on $d$, applying Theorem~\ref{thm:marginal} at each step below $d$.
\end{proof}

\begin{theorem}[Unimodality]
If $c\ge0$ and $s$ is nonincreasing, then $G(d+1)<G(d)$ implies $G(e)\le G(d)$ for all
$e\ge d$: the cost law is quasi-concave in the depth.
\end{theorem}

\begin{theorem}[Myopic stopping is exact]\label{thm:myopic}
Let $c\ge0$ and $s$ nonincreasing. If $M(e)\ge0$ for all $e<d$ and $M(d)<0$, then
$G(e)\le G(d)$ for every $e\in\mathbb{N}$.
\end{theorem}

\begin{proof}
Split on $e\le d$ (Theorem~\ref{thm:ascent}) or $e\ge d$ (Theorem~\ref{thm:norecovery}).
\end{proof}

Theorem~\ref{thm:myopic} is the algorithmic payoff: one-step lookahead is globally exact. The
first depth where the equilibrium test $s_d<c\,G(d)$ fires is the global argmax, so search
costs $O(d^\star)$ arithmetic rather than an $O(D)$ sweep with a timing run at every depth.

\begin{theorem}[Single crossing suffices]\label{thm:crossing}
Let $c\ge0$ and $d\in\mathbb{N}$. If $M(e)\ge0$ for all $e<d$ and $M(e)<0$ for all $e\ge d$,
then $G(e)\le G(d)$ for every $e$.
\end{theorem}

\begin{proof}
For $e\le d$ apply Theorem~\ref{thm:ascent}, which never used monotonicity. For $e\ge d$
induct upward: $M(n)<0$ holds directly by hypothesis, so $G(n+1)<G(n)$ at every step.
\end{proof}

The hypothesis is a property of the marginal sequence, checkable position by position, implied
by but strictly weaker than monotonicity of $s$.

\begin{lemma}[Frozen tail]
If $s_i=0$ for all $i\ge D$ then $A(e)=A(D)$ for all $e\ge D$.
\end{lemma}

\begin{theorem}[Finite support certifies]\label{thm:vanishing}
Let $c>0$, $s_i=0$ for all $i\ge D$, and $A(D)>0$. Then $M(e)<0$ for every $e\ge D$.
\end{theorem}

\begin{proof}
For $e\ge D$, $M(e)=0\cdot(1+ce)-c\,A(e)=-c\,A(D)<0$.
\end{proof}

Theorems~\ref{thm:crossing} and \ref{thm:vanishing} together turn a finite sweep into a global
certificate.

\section{Global Structure}

\begin{theorem}[Universal ceiling]\label{thm:ceiling}
If $c>0$ and $s_i\le1$ for all $i$, then $G(d)<1/c$ for every $d$.
\end{theorem}

\begin{proof}
$A(d)\le d$, so $G(d)\le d/(1+cd)<1/c$ since $cd<1+cd$.
\end{proof}

No draft model and no depth achieves more than $1/c$ verified tokens per verification-equivalent
cost; at $c=0.118$ the ceiling is $\approx 8.475$. Improving draft accuracy has strictly
diminishing returns against this wall, whereas shrinking the draft model raises the wall.

\begin{theorem}[Existence]\label{thm:exists}
Let $c>0$ and $A(d)\le B$ for all $d$. Then there is $d_0$ with $G(d)\le G(d_0)$ for all $d$.
\end{theorem}

\begin{proof}
If $G\le0$ everywhere take $d_0=0$. Otherwise fix $d_1$ with $G(d_1)>0$; for large $d$,
$G(d)\le B/(1+cd)$, which drops below $G(d_1)$ once $1+cd>B/G(d_1)$. Choose $N$ exceeding
$(B/G(d_1)-1)/c$, set $M=\max(N,d_1)$, and let $d_0$ maximise $G$ over the finite set
$\{0,\dots,M\}$. Every $d>M$ satisfies $G(d)\le B/(1+cd)<G(d_1)\le G(d_0)$.
\end{proof}

\begin{lemma}\label{lem:compstat}
If $s$ is nonincreasing then $d\,s_d\le A(d)$, hence $c\mapsto M_{c,s}(d)$ is nonincreasing.
\end{lemma}

\begin{proof}
Each of the $d$ terms of $A(d)$ is at least $s_d$. Writing
$M_{c,s}(d)=s_d+c(d\,s_d-A(d))$, the coefficient of $c$ is nonpositive.
\end{proof}

\begin{theorem}[Higher overhead never deepens the optimum]
Let $0\le c\le c'$, $s$ nonincreasing, and $M_{c,s}(d)<0$. Then $G_{c',s}(e)\le G_{c',s}(d)$
for all $e\ge d$.
\end{theorem}

\begin{proof}
Lemma~\ref{lem:compstat} gives $M_{c',s}(d)\le M_{c,s}(d)<0$; apply
Theorem~\ref{thm:norecovery} at overhead $c'$.
\end{proof}

\section{Named Survival Families}

\subsection{Geometric survival}

\begin{definition}
The \emph{geometric} profile is $s_i=r^i$, $r\in[0,1)$: the draft model agrees at each step
independently with probability $r$.
\end{definition}

\begin{proposition}
$A(d)=(1-r^d)/(1-r)$ and $A(d)\le 1/(1-r)$.
\end{proposition}

\begin{theorem}[Deepening still pays]\label{thm:geompays}
Let $c\ge0$, $0\le r<1$ and $c/(1-r)\le r^d$. Then $G(d)\le G(d+1)$.
\end{theorem}

\begin{proof}
The hypothesis gives $c\le r^d(1-r)$, so
$c\,A(d)=c(1-r^d)/(1-r)\le r^d(1-r^d)\le r^d=s_d\le s_d(1+cd)$, i.e.\ $M(d)\ge0$; conclude by
Theorem~\ref{thm:marginal}.
\end{proof}

\begin{theorem}[Logarithmic lower bound]\label{thm:loglower}
Let $c>0$, $0<r<1$. If $d\le \log\bigl((1-r)/c\bigr)/\log(1/r)$ then $G(d)\le G(d+1)$.
\end{theorem}

\begin{proof}
Multiplying by $\log(1/r)>0$ and using $\log(1/r)=-\log r$, the hypothesis is equivalent to
$\log(c/(1-r))\le d\log r=\log(r^d)$, i.e.\ $c/(1-r)\le r^d$; apply
Theorem~\ref{thm:geompays}.
\end{proof}

\begin{theorem}[Matching upper bound]
Let $c\ge0$, $0\le r<1$, $d\ge1$ and $r^d(1+cd)<c$. Then $G(e)\le G(d)$ for all $e\ge d$.
\end{theorem}

\begin{proof}
Since $d\ge1$ and all terms are nonnegative, $A(d)\ge A(1)=1$, so
$M(d)=r^d(1+cd)-c\,A(d)<c-c=0$; apply Theorem~\ref{thm:norecovery}.
\end{proof}

Both bounds behave like $\log(1/c)/\log(1/r)$ as $c\downarrow0$: \textbf{the optimal
speculation depth for geometric survival is $\Theta(\log(1/c))$}. Halving the overhead adds the
constant $\log2/\log(1/r)$ to the optimal depth, which explains why real optimal depths cluster
in the single digits.

\begin{proposition}[Calibrated instance]\label{prop:seven}
At $c=0.118$ and $r=0.8$, depth $7$ is the global optimum: $M(6)\ge0$ and $M(7)<0$, so
Theorem~\ref{thm:myopic} applies.
\end{proposition}

Note $7$ lies between the two measured register optima $4$ and $8$, as a single-rate model
must.

\subsection{Harmonic survival: divergent acceptance, finite optimum}

\begin{definition}
The \emph{harmonic} (Zipf) profile is $s_i=1/(i+1)$, the heaviest tail with vanishing
per-position acceptance. Here $A(d)=H_d\to\infty$.
\end{definition}

\begin{theorem}[Finite optimum under divergent acceptance]
For every $c>0$ there is $d_0$ with $M(d_0)<0$ and $G(d)\le G(d_0)$ for all $d$.
\end{theorem}

\begin{proof}
The profile is nonincreasing. By divergence of the harmonic series choose $D$ with
$A(D)\ge (1+c)/c+1$, so $c\,A(D)>1+c$. On the other hand
$s_D(1+cD)=(1+cD)/(D+1)\le 1+c$, since $1+cD\le(1+c)(D+1)$. Hence $M(D)<0$, so a sign change
exists; take $d_0$ least with $M(d_0)<0$ and apply Theorem~\ref{thm:myopic}, all earlier
marginals being nonnegative by minimality.
\end{proof}

Benefit grows like $\log d$, cost like $1+cd$; linear defeats logarithmic for every $c>0$.
Unbounded speculation is never optimal, however heavy the acceptance tail.

\subsection{No universal optimal depth}

\begin{definition}
The \emph{block} profile of width $N$ is $s_i=1$ for $i<N$ and $0$ otherwise: nonincreasing,
$[0,1]$-valued, with $A(d)=d$ for $d\le N$.
\end{definition}

\begin{theorem}[Impossibility]\label{thm:impossible}
For every $c>0$ and every candidate depth $d_0$ there is a legal survival curve
(nonincreasing, $0\le s_i\le1$) with $G(d_0)<G(d_0+1)$.
\end{theorem}

\begin{proof}
Take the block profile of width $d_0+1$. Then the claim is
$d_0/(1+cd_0)<(d_0+1)/(1+c(d_0+1))$, which after cross-multiplication reduces to $0<1$.
\end{proof}

Optimal speculation depth is a property of the draft/target/register triple; any published
``recommended depth'' is implicitly a claim about a workload distribution.

\section{Robustness and the Estimation Problem}

\begin{theorem}[Perturbation bounds]\label{thm:perturb}
If $|t_i-s_i|\le\varepsilon$ for all $i$, then $|A_t(d)-A_s(d)|\le\varepsilon d$ and, for
$c\ge0$,
\[
\bigl|G_{c,t}(d)-G_{c,s}(d)\bigr|\;\le\;\frac{\varepsilon d}{1+cd}\;<\;\frac{\varepsilon}{c}.
\]
\end{theorem}

\begin{proof}
Triangle inequality on $A_t(d)-A_s(d)=\sum_{i<d}(t_i-s_i)$, then divide by $1+cd>0$.
\end{proof}

\begin{theorem}[Argmax stability]\label{thm:argmax}
Let $c\ge0$ and $|t_i-s_i|\le\varepsilon$ for all $i$. If
\[
\frac{\varepsilon d}{1+cd}+\frac{\varepsilon d_0}{1+cd_0}\;<\;G_{c,s}(d_0)-G_{c,s}(d),
\]
then $G_{c,t}(d)<G_{c,t}(d_0)$.
\end{theorem}

\begin{proof}
Combine $G_{c,t}(d)\le G_{c,s}(d)+\varepsilon d/(1+cd)$ and
$G_{c,t}(d_0)\ge G_{c,s}(d_0)-\varepsilon d_0/(1+cd_0)$ from Theorem~\ref{thm:perturb} with
the hypothesis.
\end{proof}

Theorem~\ref{thm:argmax} converts a sup-norm accuracy guarantee into a certificate that a
computed argmax is the true one. Crucially, the argmax depends on $s$ only through partial
sums, in which independent or alternating errors substantially cancel.

\begin{definition}[Differencing estimator]
When instrumentation reports only the aggregate mean acceptance $m(d)$, with
$d\,m(d)=A(d)$, the tempting inversion is
$\Diff(m)_i=(i+1)m(i+1)-i\,m(i)$.
\end{definition}

\begin{proposition}[Exactness on clean data]
If $d\,m(d)=A_s(d)$ for all $d$ then $\Diff(m)_i=s_i$ for all $i$.
\end{proposition}

\begin{theorem}[Noise amplification of differencing]\label{thm:amplify}
If $|m'(d)-m(d)|\le\delta$ for all $d$, then
$\bigl|\Diff(m')_i-\Diff(m)_i\bigr|\le(2i+1)\delta$.
\end{theorem}

\begin{proof}
$\Diff(m')_i-\Diff(m)_i=(i+1)(m'(i+1)-m(i+1))-i(m'(i)-m(i))$; apply the triangle inequality
and the bound $\delta$ to each of the two terms.
\end{proof}

\begin{theorem}[The bound is attained]\label{thm:tight}
For every $\delta$ and every $i$ there are $m,m'$ with $|m'(d)-m(d)|\le|\delta|$ for all $d$
and $\Diff(m')_i-\Diff(m)_i=(2i+1)\delta$.
\end{theorem}

\begin{proof}
Take $m\equiv0$ and $m'$ supported on two points with opposite signs, $m'(i+1)=\delta$ and
$m'(i)=-\delta$. Then $\Diff(m')_i=(i+1)\delta+i\delta=(2i+1)\delta$.
\end{proof}

\begin{theorem}[The cumulative statistic is safe]
Under the same hypothesis, $|d\,m'(d)-d\,m(d)|\le d\,\delta$.
\end{theorem}

\begin{corollary}[Amplification ratio]
For every $\delta>0$ and every $i\ge1$,
$\tfrac32(i+1)\delta\le(2i+1)\delta<2(i+1)\delta$.
\end{corollary}

The worst-case error of the differenced per-position estimate is between $1.5\times$ and
$2\times$ that of the cumulative statistic it came from, tending to $2\times$; and the
amplification is multiplicative in the index, hence largest exactly where the signal $s_i$ is
smallest. \textbf{Aggregate-to-pointwise inversion by differencing is a variance-doubling
operation.} If per-position quantities are needed they must be instrumented per position.

\section{The Measured Instance}\label{sec:measured}

\subsection{Setup}
A fine depth sweep $d\in\{1,\dots,8\}$ was run over two prompt registers --- natural-language
prose and source code --- with a $0.5$B-parameter draft model speculating for a CPU-hosted
$7$B-parameter target, greedy decoding, fixed seed, context $\le1024$, eight threads. The
marginal drafting overhead was measured as $c=0.118$. An earlier, independent round measured
end-to-end throughput at each depth and located the optima directly: \textbf{depth $4$ for
prose, depth $8$ for code}. The new round recorded cumulative acceptance and applied the
differencing estimator, yielding (to three decimals):

